-- 1. Tribunal constitutionnel (fonction 490 - PL-d) INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Pologne – Tribunal Constitutionnel (Trybunał Konstytucyjny)', 'Président, vice-président et juges du Tribunal constitutionnel polonais (catégorie PL-d)', 'pl_pep_constitutional_tribunal', 'PEP', 'https://trybunal.gov.pl/', 'pl-pep-constitutional-tribunal', 'D:/test parser 2/plugins/swiftcheck-aml-pl-pep-constitutional-tribunal-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"url": "https://trybunal.gov.pl/o-trybunale/sedziowie-trybunalu"}', 168, 12, 'Données publiques ouvertes : citer la source', 'Trybunał Konstytucyjny Rzeczypospolitej Polskiej', 'Présidente (Julia Przyłębska), vice-président et ensemble des juges du Tribunal constitutionnel.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Président, vice-président et magistrats du Trybunał Konstytucyjny', NULL FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.country_iso = 'PL' AND f.id = 490 AND p.dataset_name = 'pl_pep_constitutional_tribunal';
